config.code:
import json, re

raw = intent_detection_output   

if isinstance(raw, dict):
    parsed = raw
else:
    clean = re.sub(r'^```(?:json)?\s*', '', str(raw).strip(), flags=re.IGNORECASE)
    clean = re.sub(r'\s*```$', '', clean).strip()
    try:
        parsed = json.loads(clean)
    except Exception:
        output = str(raw).strip()
        parsed = None

if parsed is not None:
    candidate = parsed.get('flag') or parsed.get('route') or parsed.get('action')
    if not candidate:
        candidate = next((str(v) for v in parsed.values() if isinstance(v, str)), str(list(parsed.values())[0]))
    output = str(candidate).strip()

